/* ===== src/entities/Player.js ===== */
// Player 只负责“女孩显示在哪里、如何平滑移动”。具体能不能走由 GameScene 判断。
class Player {
  constructor(scene, worldX, worldY) {
    this.scene = scene;
    this.worldX = worldX;
    this.worldY = worldY;
    this.directionName = 'down';
    this.walkFlipX = false;
    this.isWalking = false;

    // 阴影和人物分开移动，能让小女孩更像站在地面上。
    this.shadow = scene.add.ellipse(worldX, worldY + 30, 64, 18, 0x173328, 0.3).setDepth(13);
    this.sprite = scene.add.sprite(worldX, worldY, 'player-idle-5dir', 0).setDepth(14).setScale(0.39);
    this.playAnimation('idle');
  }

  setPosition(worldX, worldY) {
    this.worldX = worldX;
    this.worldY = worldY;
    this.sprite.setPosition(worldX, worldY);
    this.shadow.setPosition(worldX, worldY + 26);
  }

  moveBy(deltaX, deltaY) {
    if (Math.abs(deltaX) > 0.01 || Math.abs(deltaY) > 0.01) {
      this.updateDirection(deltaX, deltaY);
      this.playAnimation('walk');
    } else {
      this.stopMoving();
    }
    this.setPosition(this.worldX + deltaX, this.worldY + deltaY);
  }

  stopMoving() {
    this.playAnimation('idle');
  }

  updateDirection(deltaX, deltaY) {
    const absX = Math.abs(deltaX);
    const absY = Math.abs(deltaY);
    let nextDirection = 'left';
    // 这组角色素材的侧身方向与最初预估相反，所以向左时才需要水平翻转。
    // 这样按左键会面向左，按右键会面向右，斜向移动也会跟着正确转身。
    let flipX = deltaX < 0;

    if (absY > absX * 1.35) {
      nextDirection = deltaY > 0 ? 'down' : 'up';
      flipX = false;
    } else if (absX > absY * 1.35) {
      nextDirection = 'left';
    } else {
      nextDirection = deltaY > 0 ? 'left-down' : 'left-up';
    }

    this.directionName = nextDirection;
    this.walkFlipX = flipX;
    this.sprite.setFlipX(flipX);
  }

  playAnimation(type) {
    const animationKey = `player-${type}-${this.directionName}`;
    // 待机图和行走图的侧身朝向相反：走路按移动方向翻转，停下时左右要反过来。
    const usesSideFrame = this.directionName.includes('left');
    const shouldFlipX = type === 'idle' && usesSideFrame ? !this.walkFlipX : this.walkFlipX;
    this.sprite.setFlipX(shouldFlipX);
    if (this.sprite.anims.currentAnim?.key === animationKey) return;
    this.sprite.play(animationKey);
  }

  destroy() {
    this.sprite.destroy();
    this.shadow.destroy();
  }
}


/* ===== src/systems/AudioManager.js ===== */

// 不依赖外部音频文件的轻量声音系统。以后加入 mp3 后可以在这里替换成正式音乐。
class AudioManagerClass {
  constructor() {
    this.context = null;
    this.musicTimer = null;
    this.noteIndex = 0;
    this.notes = [261.63, 329.63, 392, 329.63, 293.66, 349.23, 440, 392];
  }

  ensureContext() {
    if (!this.context) this.context = new (window.AudioContext || window.webkitAudioContext)();
    if (this.context.state === 'suspended') this.context.resume();
  }

  beep(frequency, duration = 0.09, volume = 0.12) {
    this.ensureContext();
    const oscillator = this.context.createOscillator();
    const gain = this.context.createGain();
    const now = this.context.currentTime;
    oscillator.frequency.value = frequency;
    oscillator.type = 'triangle';
    gain.gain.setValueAtTime(volume * GameState.settings.soundVolume, now);
    gain.gain.exponentialRampToValueAtTime(0.001, now + duration);
    oscillator.connect(gain).connect(this.context.destination);
    oscillator.start(now);
    oscillator.stop(now + duration);
  }

  startMusic() {
    this.ensureContext();
    if (this.musicTimer) return;
    this.musicTimer = window.setInterval(() => {
      this.beep(this.notes[this.noteIndex++ % this.notes.length], 0.55, 0.035 * GameState.settings.musicVolume);
    }, 680);
  }

  toggleMusic(enabled) {
    if (enabled) this.startMusic();
    else if (this.musicTimer) {
      window.clearInterval(this.musicTimer);
      this.musicTimer = null;
    }
  }
}

const AudioManager = new AudioManagerClass();


/* ===== src/systems/FullscreenManager.js ===== */
// FullscreenManager 统一使用浏览器的页面全屏能力，保证画布、视频背景和网页按钮一起进入全屏。
const FullscreenManager = {
  isActive() {
    return Boolean(document.fullscreenElement || document.webkitFullscreenElement);
  },

  async toggle() {
    if (this.isActive()) {
      const exit = document.exitFullscreen || document.webkitExitFullscreen;
      if (!exit) throw new Error('当前浏览器不支持退出全屏。');
      await exit.call(document);
      return;
    }

    // 让整个网页根节点全屏，而不是只放大 Phaser 画布，避免透明画布外出现黑屏。
    const target = document.documentElement;
    const request = target.requestFullscreen || target.webkitRequestFullscreen;
    if (!request) throw new Error('当前浏览器不支持全屏显示。');
    await request.call(target);
  },
};


/* ===== src/systems/Board.js ===== */

// Board 负责把文字地图变成遗迹场景，并集中管理钥匙、出口和守卫等寻路规则。
class Board {
  constructor(scene, level, offsetX, offsetY, tileSize = TILE_SIZE) {
    this.scene = scene;
    this.level = level;
    this.offsetX = offsetX;
    this.offsetY = offsetY;
    this.tileSize = tileSize;
    this.rows = level.map;
    this.height = this.rows.length;
    this.width = Math.max(...this.rows.map((row) => row.length));
    this.baseTiles = new Map();
    this.tileImages = new Map();
    this.fragments = new Map();
    this.keys = new Map();
    this.weapons = new Map();
    // 守卫巡逻时要绕开仍未收集的武器、钥匙、碎片，避免直接从道具上穿过去。
    this.guardianBlockedPickups = new Set();
    this.guardians = [];
    this.playerStart = { x: 1, y: 1 };
    this.fragmentsCollected = 0;
    this.totalFragments = 0;
    this.keysCollected = 0;
    this.totalKeys = 0;
    this.doorsOpen = false;
    // 第一关使用正式大底图与 PNG 道具素材；其它关卡继续沿用代码生成的临时素材。
    this.isLevelOneArt = level.id === 1;
  }

  build() {
    for (let y = 0; y < this.height; y += 1) {
      for (let x = 0; x < this.width; x += 1) {
        this.createCell(x, y, this.rows[y][x] ?? TILE_TYPES.WALL);
      }
    }
    if (this.isLevelOneArt) this.createLevelOneStoneDecorations();
    this.updateExit();
  }

  createCell(x, y, char) {
    const position = this.gridToWorld(x, y);
    const key = this.key(x, y);
    const isWall = char === TILE_TYPES.WALL;
    this.baseTiles.set(key, isWall ? TILE_TYPES.WALL : TILE_TYPES.FLOOR);

    if (!this.isLevelOneArt) {
      const groundKey = isWall ? 'wall' : ((x * 3 + y * 5) % 4 === 0 ? 'floor-alt' : 'floor');
      // 地面和墙体铺满整个格子，避免地图放大后出现空隙。
      this.tileImages.set(key, this.scene.add.image(position.x, position.y, groundKey).setDisplaySize(this.tileSize, this.tileSize).setDepth(1));
    } else if (isWall && !this.isLevelOneOuterWall(x, y) && !this.isLevelOneStoneGroupCell(x, y)) {
      // 第一关大背景已经包含草地格子和边缘装饰，这里只补真正会挡路的零散墙体。
      this.tileImages.set(key, this.scene.add.image(position.x, position.y, 'wall').setDisplaySize(this.tileSize, this.tileSize).setAlpha(0.84).setDepth(3));
    }

    if (isWall) return;

    if (char === TILE_TYPES.PLAYER) this.playerStart = { x, y };
    if (char === TILE_TYPES.FRAGMENT || char === TILE_TYPES.KEY || char === TILE_TYPES.WEAPON) this.guardianBlockedPickups.add(key);
    const overlayTexture = this.getOverlayTexture(char);
    if (overlayTexture) {
      const overlay = char === TILE_TYPES.GUARDIAN && this.isLevelOneArt
        ? this.scene.add.sprite(position.x, position.y, overlayTexture, 0)
        : this.scene.add.image(position.x, position.y, overlayTexture);
      overlay.setDepth(char === TILE_TYPES.GUARDIAN ? 7 : 3);
      this.applyLevelOneOverlayStyle(overlay, char);
      this.tileImages.set(`${key}:overlay`, overlay);
      if (char === TILE_TYPES.FRAGMENT || char === TILE_TYPES.KEY || char === TILE_TYPES.WEAPON) {
        this.createPickupFloat(overlay, x, y);
      }
    }

    if (char === TILE_TYPES.FRAGMENT) {
      this.fragments.set(key, this.tileImages.get(`${key}:overlay`));
      this.totalFragments += 1;
    }
    if (char === TILE_TYPES.KEY) {
      this.keys.set(key, this.tileImages.get(`${key}:overlay`));
      this.totalKeys += 1;
    }
    if (char === TILE_TYPES.WEAPON) this.weapons.set(key, this.tileImages.get(`${key}:overlay`));
    if (char === TILE_TYPES.GUARDIAN) this.createGuardian(x, y, this.tileImages.get(`${key}:overlay`));
    if (Object.values(TILE_TYPES).includes(char) && char !== TILE_TYPES.PLAYER) {
      const walkableOverlay = char === TILE_TYPES.FRAGMENT || char === TILE_TYPES.KEY || char === TILE_TYPES.WEAPON || char === TILE_TYPES.GUARDIAN;
      this.baseTiles.set(key, walkableOverlay ? TILE_TYPES.FLOOR : char);
    }
  }

  getOverlayTexture(char) {
    if (this.isLevelOneArt) {
      return {
        [TILE_TYPES.DOOR]: 'level1-door',
        [TILE_TYPES.SWAMP]: 'swamp',
        [TILE_TYPES.FRAGMENT]: 'level1-fragment',
        [TILE_TYPES.KEY]: 'level1-key',
        [TILE_TYPES.WEAPON]: 'level1-weapon',
        [TILE_TYPES.GUARDIAN]: 'level1-guardian',
      }[char];
    }

    return {
      [TILE_TYPES.DOOR]: 'door-closed',
      [TILE_TYPES.SWAMP]: 'swamp',
      [TILE_TYPES.FRAGMENT]: 'fragment',
      [TILE_TYPES.KEY]: 'key',
      [TILE_TYPES.WEAPON]: 'weapon',
      [TILE_TYPES.GUARDIAN]: 'guardian',
    }[char];
  }

  applyLevelOneOverlayStyle(overlay, char) {
    if (!this.isLevelOneArt) return;
    if (char === TILE_TYPES.DOOR) overlay.setScale(0.72);
    if (char === TILE_TYPES.KEY) overlay.setScale(0.58);
    if (char === TILE_TYPES.WEAPON) overlay.setScale(0.56);
    if (char === TILE_TYPES.FRAGMENT) overlay.setScale(0.62);
    if (char === TILE_TYPES.GUARDIAN) overlay.setScale(0.24);

    // PNG 图片的透明边和视觉重心不完全一样，所以第一关按参考图做少量微调。
    const offset = {
      [TILE_TYPES.DOOR]: { x: 0, y: -2 },
      [TILE_TYPES.KEY]: { x: 0, y: -5 },
      [TILE_TYPES.WEAPON]: { x: 0, y: -2 },
      [TILE_TYPES.FRAGMENT]: { x: 4, y: -3 },
      [TILE_TYPES.GUARDIAN]: { x: 0, y: 0 },
    }[char];
    if (offset) overlay.setPosition(overlay.x + offset.x, overlay.y + offset.y);
  }

  createPickupFloat(overlay, gridX, gridY) {
    // 物品基于“微调后的真实位置”轻轻漂浮，避免之前从偏移点跳回格子中心。
    const baseY = overlay.y;
    const phaseDelay = ((gridX * 137 + gridY * 89) % 420);
    this.scene.tweens.add({
      targets: overlay,
      y: baseY - 3,
      duration: 1350,
      delay: phaseDelay,
      yoyo: true,
      repeat: -1,
      ease: 'Sine.inOut',
    });
  }

  isLevelOneOuterWall(x, y) {
    // 边界墙只负责挡住玩家，不画出来，避免把正式背景框住。
    return x === 0 || y === 0 || x === this.width - 1 || y === this.height - 1;
  }

  isLevelOneStoneGroupCell(x, y) {
    // 两组横向石头图片覆盖这些墙格，所以不再重复画单格墙。
    return ((y === 1 || y === 3) && x >= 4 && x <= 6);
  }

  createLevelOneStoneDecorations() {
    this.addLevelOneStoneGroup('level1-stones-a', 4, 1, 3, 1);
    this.addLevelOneStoneGroup('level1-stones-b', 4, 3, 3, 1);
  }

  addLevelOneStoneGroup(textureKey, gridX, gridY, gridWidth, gridHeight) {
    const x = this.offsetX + (gridX + gridWidth / 2) * this.tileSize;
    const y = this.offsetY + (gridY + gridHeight / 2) * this.tileSize;
    const stones = this.scene.add.image(x, y, textureKey).setDepth(4);
    // 石头组收在三格内部，外轮廓刚好贴近参考图里的格子边线。
    stones.setDisplaySize(gridWidth * this.tileSize - 18, this.tileSize * 0.98);
    this.tileImages.set(`level1:stones:${gridX},${gridY}`, stones);
  }

  // 守卫会持续定位玩家，并根据地图障碍快速调整追踪方向。
  createGuardian(x, y, sprite) {
    const position = this.gridToWorld(x, y);
    // 守卫脚下增加一层柔和投影，让它和地面更贴合。
    const shadow = this.scene.add.ellipse(position.x, position.y + 16, 42, 13, 0x173328, 0.28).setDepth(6);
    const guardian = {
      worldX: position.x,
      worldY: position.y,
      direction: { x: 0, y: 0 },
      nextTurnAt: 0,
      speed: 88,
      sprite,
      shadow,
    };
    this.chooseGuardianDirection(guardian);
    this.guardians.push(guardian);
  }

  key(x, y) {
    return `${x},${y}`;
  }

  getTile(x, y) {
    return this.baseTiles.get(this.key(x, y)) ?? TILE_TYPES.WALL;
  }

  isBlocked(x, y) {
    const tile = this.getTile(x, y);
    return tile === TILE_TYPES.WALL || (tile === TILE_TYPES.DOOR && !this.doorsOpen);
  }

  getWorldBounds() {
    return {
      x: this.offsetX,
      y: this.offsetY,
      width: this.width * this.tileSize,
      height: this.height * this.tileSize,
      right: this.offsetX + this.width * this.tileSize,
      bottom: this.offsetY + this.height * this.tileSize,
    };
  }

  gridToWorld(x, y) {
    return {
      x: this.offsetX + x * this.tileSize + this.tileSize / 2,
      y: this.offsetY + y * this.tileSize + this.tileSize / 2,
    };
  }

  worldToGrid(worldX, worldY) {
    return {
      x: Math.floor((worldX - this.offsetX) / this.tileSize),
      y: Math.floor((worldY - this.offsetY) / this.tileSize),
    };
  }

  getTileAtWorld(worldX, worldY) {
    const grid = this.worldToGrid(worldX, worldY);
    return this.getTile(grid.x, grid.y);
  }

  isWorldBlocked(worldX, worldY, radius = 18) {
    const samplePoints = [
      { x: worldX, y: worldY },
      { x: worldX - radius, y: worldY - radius },
      { x: worldX + radius, y: worldY - radius },
      { x: worldX - radius, y: worldY + radius },
      { x: worldX + radius, y: worldY + radius },
      { x: worldX, y: worldY - radius },
      { x: worldX, y: worldY + radius },
      { x: worldX - radius, y: worldY },
      { x: worldX + radius, y: worldY },
    ];
    return samplePoints.some((point) => {
      const grid = this.worldToGrid(point.x, point.y);
      return this.isBlocked(grid.x, grid.y);
    });
  }

  collectKeyAtWorld(worldX, worldY) {
    if (!this.areGuardiansCleared()) return false;
    for (const [key, image] of this.keys.entries()) {
      if (Phaser.Math.Distance.Between(worldX, worldY, image.x, image.y) > 38) continue;
      image.destroy();
      this.keys.delete(key);
      this.guardianBlockedPickups.delete(key);
      this.keysCollected += 1;
      this.updateExit();
      return true;
    }
    return false;
  }

  collectFragmentAtWorld(worldX, worldY) {
    for (const [key, image] of this.fragments.entries()) {
      if (Phaser.Math.Distance.Between(worldX, worldY, image.x, image.y) > 42) continue;
      image.destroy();
      this.fragments.delete(key);
      this.guardianBlockedPickups.delete(key);
      this.fragmentsCollected += 1;
      this.updateExit();
      return true;
    }
    return false;
  }

  areFragmentsCollected() {
    return this.fragmentsCollected === this.totalFragments;
  }

  isNearKey(worldX, worldY) {
    return [...this.keys.values()].some((image) => Phaser.Math.Distance.Between(worldX, worldY, image.x, image.y) <= 42);
  }

  collectWeaponAtWorld(worldX, worldY) {
    for (const [key, image] of this.weapons.entries()) {
      if (Phaser.Math.Distance.Between(worldX, worldY, image.x, image.y) > 42) continue;
      image.destroy();
      this.weapons.delete(key);
      this.guardianBlockedPickups.delete(key);
      return true;
    }
    return false;
  }

  areGuardiansCleared() {
    return this.guardians.length === 0;
  }

  isWorldTile(worldX, worldY, tileType) {
    return this.getTileAtWorld(worldX, worldY) === tileType;
  }

  isAtOpenDoor(worldX, worldY) {
    return this.doorsOpen && this.isWorldTile(worldX, worldY, TILE_TYPES.DOOR);
  }

  updateExit() {
    this.doorsOpen = this.keysCollected === this.totalKeys && this.areFragmentsCollected();
    this.baseTiles.forEach((tile, key) => {
      if (tile !== TILE_TYPES.DOOR) return;
      const door = this.tileImages.get(`${key}:overlay`);
      if (!door) return;
      if (this.isLevelOneArt) {
        door.setTexture('level1-door').setAlpha(this.doorsOpen ? 0.46 : 1).setTint(this.doorsOpen ? 0xb7ff9c : 0xffffff);
      } else {
        door.setTexture(this.doorsOpen ? 'door-open' : 'door-closed');
      }
    });
  }

  // 每一帧都让守卫追踪玩家；返回碰到玩家的守卫，交给 GameScene 判断胜负。
  updateGuardians(playerWorldX, playerWorldY, delta) {
    for (const guardian of this.guardians) {
      guardian.nextTurnAt -= delta;
      if (guardian.nextTurnAt <= 0) this.chooseGuardianDirection(guardian, playerWorldX, playerWorldY);

      const distance = guardian.speed * (delta / 1000);
      const nextWorldX = guardian.worldX + guardian.direction.x * distance;
      const nextWorldY = guardian.worldY + guardian.direction.y * distance;
      if (this.isGuardianBlocked(nextWorldX, nextWorldY)) {
        this.chooseGuardianDirection(guardian, playerWorldX, playerWorldY);
      } else {
        guardian.worldX = nextWorldX;
        guardian.worldY = nextWorldY;
        guardian.sprite.setPosition(guardian.worldX, guardian.worldY);
        guardian.shadow?.setPosition(guardian.worldX, guardian.worldY + 16);
      }
      if (Phaser.Math.Distance.Between(playerWorldX, playerWorldY, guardian.worldX, guardian.worldY) < 38) return guardian;
    }
    return null;
  }

  chooseGuardianDirection(guardian, targetWorldX = null, targetWorldY = null) {
    const directions = [
      { x: 1, y: 0 },
      { x: -1, y: 0 },
      { x: 0, y: 1 },
      { x: 0, y: -1 },
    ];
    const availableDirections = directions.filter((direction) => {
      const testX = guardian.worldX + direction.x * 34;
      const testY = guardian.worldY + direction.y * 34;
      return !this.isGuardianBlocked(testX, testY);
    });
    const choices = availableDirections.length > 0 ? availableDirections : directions;
    const hasTarget = Number.isFinite(targetWorldX) && Number.isFinite(targetWorldY);
    const pathDirection = hasTarget ? this.findGuardianPathDirection(guardian, targetWorldX, targetWorldY) : null;
    const matchedPathDirection = pathDirection
      ? choices.find((direction) => direction.x === pathDirection.x && direction.y === pathDirection.y)
      : null;

    if (matchedPathDirection) {
      guardian.direction = matchedPathDirection;
    } else if (hasTarget) {
      // 找不到完整路线时，也优先选择下一步后距离玩家更近的方向。
      guardian.direction = [...choices].sort((a, b) => {
        const nextAX = guardian.worldX + a.x * 34;
        const nextAY = guardian.worldY + a.y * 34;
        const nextBX = guardian.worldX + b.x * 34;
        const nextBY = guardian.worldY + b.y * 34;
        return Phaser.Math.Distance.Between(nextAX, nextAY, targetWorldX, targetWorldY)
          - Phaser.Math.Distance.Between(nextBX, nextBY, targetWorldX, targetWorldY);
      })[0];
    } else {
      guardian.direction = Phaser.Utils.Array.GetRandom(choices);
    }

    // 追踪时频繁重新定位玩家，玩家停住或移动都会被快速锁定。
    guardian.nextTurnAt = hasTarget ? Phaser.Math.Between(120, 240) : Phaser.Math.Between(650, 1500);
    this.updateGuardianFacing(guardian);
  }

  // 通过简单寻路找出守卫下一步该往哪走，让它能更快靠近玩家。
  findGuardianPathDirection(guardian, targetWorldX, targetWorldY) {
    const start = this.worldToGrid(guardian.worldX, guardian.worldY);
    const target = this.worldToGrid(targetWorldX, targetWorldY);
    if (start.x === target.x && start.y === target.y) return null;

    const directions = [
      { x: 1, y: 0 },
      { x: -1, y: 0 },
      { x: 0, y: 1 },
      { x: 0, y: -1 },
    ].sort((a, b) => {
      const nextA = { x: start.x + a.x, y: start.y + a.y };
      const nextB = { x: start.x + b.x, y: start.y + b.y };
      return Math.abs(nextA.x - target.x) + Math.abs(nextA.y - target.y)
        - (Math.abs(nextB.x - target.x) + Math.abs(nextB.y - target.y));
    });
    const queue = [{ x: start.x, y: start.y, firstDirection: null }];
    const visited = new Set([this.key(start.x, start.y)]);

    while (queue.length > 0) {
      const current = queue.shift();
      for (const direction of directions) {
        const next = { x: current.x + direction.x, y: current.y + direction.y };
        const nextKey = this.key(next.x, next.y);
        if (visited.has(nextKey) || this.isGuardianGridBlocked(next.x, next.y)) continue;
        const firstDirection = current.firstDirection ?? direction;
        if (next.x === target.x && next.y === target.y) return firstDirection;
        visited.add(nextKey);
        queue.push({ x: next.x, y: next.y, firstDirection });
      }
    }
    return null;
  }

  // 守卫专用阻挡规则：墙、沼泽、门和未收集道具都会让守卫换方向。
  isGuardianGridBlocked(x, y) {
    const tile = this.getTile(x, y);
    const hasPickup = this.guardianBlockedPickups.has(this.key(x, y));
    return hasPickup || tile === TILE_TYPES.WALL || tile === TILE_TYPES.SWAMP || tile === TILE_TYPES.DOOR;
  }

  updateGuardianFacing(guardian) {
    if (!this.isLevelOneArt || !guardian.sprite?.setFrame) return;
    const { x, y } = guardian.direction;
    // decor-guardian.png 是竖排 4 帧：下、左、上、右。
    const frameIndex = Math.abs(x) > Math.abs(y)
      ? (x < 0 ? 1 : 3)
      : (y < 0 ? 2 : 0);
    guardian.sprite.setFlipX(false);
    guardian.sprite.setFrame(frameIndex);
  }

  isGuardianBlocked(worldX, worldY) {
    const samplePoints = [
      { x: worldX, y: worldY },
      { x: worldX - 22, y: worldY - 22 },
      { x: worldX + 22, y: worldY - 22 },
      { x: worldX - 22, y: worldY + 22 },
      { x: worldX + 22, y: worldY + 22 },
    ];
    return samplePoints.some((point) => {
      const grid = this.worldToGrid(point.x, point.y);
      return this.isGuardianGridBlocked(grid.x, grid.y);
    });
  }

  defeatGuardian(guardian) {
    const index = this.guardians.indexOf(guardian);
    if (index === -1) return false;
    this.guardians.splice(index, 1);
    this.scene.tweens.killTweensOf(guardian.sprite);
    this.scene.tweens.killTweensOf(guardian.shadow);
    this.scene.tweens.add({
      targets: [guardian.sprite, guardian.shadow],
      alpha: 0,
      scale: 0.35,
      duration: 180,
      ease: 'Sine.in',
      onComplete: () => {
        guardian.sprite.destroy();
        guardian.shadow?.destroy();
      },
    });
    return true;
  }

  destroy() {
    this.guardians.forEach((guardian) => guardian.shadow?.destroy());
    this.tileImages.forEach((image) => image.destroy());
  }
}


/* ===== src/ui/UIFactory.js ===== */

// 所有菜单按钮都通过这一处制作，颜色和互动效果会保持统一。
const UIFactory = {
  createButton(scene, x, y, label, onClick, width = 270) {
    const container = scene.add.container(x, y).setDepth(30);
    const background = scene.add.rectangle(0, 0, width, 54, 0x254f3e, 0.96).setStrokeStyle(2, 0xc9e6b3);
    const text = scene.add.text(0, 0, label, { fontFamily: 'Microsoft YaHei', fontSize: '22px', color: '#fff8d8' }).setOrigin(0.5);
    container.add([background, text]).setSize(width, 54).setInteractive({ useHandCursor: true });
    container.on('pointerover', () => { background.setFillStyle(0x3c7657); container.setScale(1.04); });
    container.on('pointerout', () => { background.setFillStyle(0x254f3e); container.setScale(1); });
    container.on('pointerdown', () => { AudioManager.beep(523.25); onClick(); });
    return container;
  },

  // 游戏顶部使用纯图标按钮，避免文字占据地图空间；label 只会在鼠标悬停时作为小提示出现。
  createIconButton(scene, x, y, icon, label, onClick) {
    const container = scene.add.container(x, y).setDepth(30);
    const background = scene.add.graphics();
    const symbol = scene.add.graphics();
    const tooltipBackground = scene.add.rectangle(0, -43, Math.max(76, label.length * 18), 26, 0x0b2019, 0.94)
      .setStrokeStyle(1, 0xc9e6b3)
      .setVisible(false);
    const tooltip = scene.add.text(0, -43, label, {
      fontFamily: 'Microsoft YaHei',
      fontSize: '14px',
      color: '#fff8d8',
    }).setOrigin(0.5).setVisible(false);

    background.fillStyle(0x254f3e, 0.98).fillRoundedRect(-27, -27, 54, 54, 14);
    background.lineStyle(2, 0xc9e6b3, 0.9).strokeRoundedRect(-27, -27, 54, 54, 14);

    if (icon === 'home') {
      // 房子图标代表回到主菜单。
      symbol.fillStyle(0xfff1bd).fillTriangle(0, -17, -18, -1, 18, -1);
      symbol.fillStyle(0xfff1bd).fillRoundedRect(-13, -2, 26, 17, 2);
      symbol.fillStyle(0x254f3e).fillRect(-3, 5, 6, 10);
    } else {
      // 圆形箭头图标代表从头重新开始当前关卡。
      symbol.lineStyle(5, 0xfff1bd, 1).beginPath().arc(0, 0, 14, 0.55, 5.55, false).strokePath();
      symbol.fillStyle(0xfff1bd).fillTriangle(17, -13, 18, 3, 5, -3);
    }

    container.add([background, symbol, tooltipBackground, tooltip]).setSize(54, 54).setInteractive({ useHandCursor: true });
    container.on('pointerover', () => {
      background.clear().fillStyle(0x3c7657, 1).fillRoundedRect(-27, -27, 54, 54, 14).lineStyle(2, 0xe8f4cc, 1).strokeRoundedRect(-27, -27, 54, 54, 14);
      tooltipBackground.setVisible(true);
      tooltip.setVisible(true);
      container.setScale(1.06);
    });
    container.on('pointerout', () => {
      background.clear().fillStyle(0x254f3e, 0.98).fillRoundedRect(-27, -27, 54, 54, 14).lineStyle(2, 0xc9e6b3, 0.9).strokeRoundedRect(-27, -27, 54, 54, 14);
      tooltipBackground.setVisible(false);
      tooltip.setVisible(false);
      container.setScale(1);
    });
    container.on('pointerdown', () => { AudioManager.beep(523.25); onClick(); });
    return container;
  },

  createPanel(scene, x, y, width, height) {
    return scene.add.rectangle(x, y, width, height, 0x102d25, 0.94).setStrokeStyle(3, 0xd7c788).setDepth(20);
  },
};


/* ===== src/ui/LoadingDomUI.js ===== */
// LoadingDomUI 控制网页层的加载条，避免本地直接打开游戏时 Phaser 无法读取图片的问题。
const LoadingDomUI = {
  show() {
    const layer = document.getElementById('loading-ui-layer');
    layer.style.display = 'grid';
    this.setProgress(0);
  },

  setProgress(percent) {
    const safePercent = Math.min(100, Math.max(0, Math.round(percent)));
    document.getElementById('loading-progress-mask').style.width = `${safePercent}%`;
    document.getElementById('loading-progress-text').textContent = `正在进入森林遗迹 ${safePercent}%`;
  },

  hide() {
    document.getElementById('loading-ui-layer').style.display = 'none';
  },
};


/* ===== src/ui/TutorialDomUI.js ===== */
// TutorialDomUI 控制探险手册的网页图片层，避免 Phaser 在本地运行时无法读取 PNG 素材。
const TutorialDomUI = {
  show({ onStart, onMenu }) {
    const layer = document.getElementById('tutorial-ui-layer');
    document.getElementById('tutorial-start').onclick = onStart;
    document.getElementById('tutorial-menu').onclick = onMenu;
    layer.style.display = 'block';
  },

  hide() {
    const layer = document.getElementById('tutorial-ui-layer');
    layer.style.display = 'none';
    document.getElementById('tutorial-start').onclick = null;
    document.getElementById('tutorial-menu').onclick = null;
  },
};


/* ===== src/ui/LevelSelectDomUI.js ===== */
// LevelSelectDomUI 管理关卡选择的网页图片层。
// 采用浏览器原生 img 标签，能兼容用户直接双击 index.html 的运行方式。
const LevelSelectDomUI = {
  // 保存监听函数，关闭页面时必须移除，避免重复打开关卡页后重复执行。
  _onLayoutChange: null,

  show({ levels, unlockedLevel, completedLevels, onLevel, onBack }) {
    const layer = document.getElementById('level-select-ui-layer');
    const grid = document.getElementById('level-select-grid');
    const backButton = document.getElementById('level-select-back');

    // 每次打开都重新生成卡片，保证进度更新后“已通过”和“未解锁”状态准确。
    grid.replaceChildren();
    levels.forEach((level) => {
      const unlocked = level.id <= unlockedLevel;
      const completed = completedLevels.includes(level.id);
      const card = document.createElement(unlocked ? 'button' : 'div');
      card.className = `level-card ${unlocked ? 'is-unlocked' : 'is-locked'}`;
      card.setAttribute('role', 'listitem');

      const background = document.createElement('img');
      background.src = unlocked
        ? './assets/images/ui/level-select/level-card-unlocked.png'
        : './assets/images/ui/level-select/level-card-locked.png';
      background.alt = '';
      background.draggable = false;
      card.append(background);

      if (unlocked) {
        card.type = 'button';
        card.setAttribute('aria-label', `进入第 ${level.id} 关：${level.name}`);

        const title = document.createElement('span');
        title.className = 'level-card-title';
        title.textContent = `第 ${level.id} 关`;
        card.append(title);

        const name = document.createElement('span');
        name.className = 'level-card-name';
        name.textContent = level.name;
        card.append(name);

        if (completed) {
          const status = document.createElement('span');
          status.className = 'level-card-status';
          status.textContent = '已通过';
          card.append(status);
        }

        card.onclick = () => onLevel(level.id);
      } else {
        card.setAttribute('aria-label', `第 ${level.id} 关尚未解锁`);
      }

      grid.append(card);
    });

    backButton.onclick = onBack;
    layer.style.display = 'block';
    this.bindLayoutEvents();
    this.updateLayout();
  },

  hide() {
    const layer = document.getElementById('level-select-ui-layer');
    const grid = document.getElementById('level-select-grid');
    const backButton = document.getElementById('level-select-back');
    if (!layer) return;

    // 关闭时清理事件和卡片，避免离开本场景后仍触发旧页面的点击逻辑。
    layer.style.display = 'none';
    grid.replaceChildren();
    backButton.onclick = null;
    this.unbindLayoutEvents();
    this.resetLayout();
  },

  // 监听全屏切换和窗口尺寸变化。无论玩家使用按钮进入全屏，还是改变窗口大小，都会重新居中。
  bindLayoutEvents() {
    if (this._onLayoutChange) return;
    this._onLayoutChange = () => this.updateLayout();
    document.addEventListener('fullscreenchange', this._onLayoutChange);
    document.addEventListener('webkitfullscreenchange', this._onLayoutChange);
    window.addEventListener('resize', this._onLayoutChange);
  },

  unbindLayoutEvents() {
    if (!this._onLayoutChange) return;
    document.removeEventListener('fullscreenchange', this._onLayoutChange);
    document.removeEventListener('webkitfullscreenchange', this._onLayoutChange);
    window.removeEventListener('resize', this._onLayoutChange);
    this._onLayoutChange = null;
  },

  // 全屏时保持 1280×720 的设计尺寸，再按屏幕可容纳的最大比例整体放大。
  updateLayout() {
    const layer = document.getElementById('level-select-ui-layer');
    if (!layer) return;

    const isFullscreen = Boolean(document.fullscreenElement || document.webkitFullscreenElement);
    if (!isFullscreen) {
      this.resetLayout();
      return;
    }

    const scale = Math.min(window.innerWidth / 1280, window.innerHeight / 720);
    layer.style.width = '1280px';
    layer.style.height = '720px';
    layer.style.transformOrigin = 'center center';
    layer.style.transform = `translate(-50%, -50%) scale(${scale})`;
  },

  // 回到普通窗口后交还给 CSS 默认布局，避免残留的全屏缩放影响下一次打开。
  resetLayout() {
    const layer = document.getElementById('level-select-ui-layer');
    if (!layer) return;
    layer.style.removeProperty('width');
    layer.style.removeProperty('height');
    layer.style.removeProperty('transform-origin');
    layer.style.removeProperty('transform');
  },
};


/* ===== src/ui/MenuDomUI.js ===== */
// MenuDomUI 管理主菜单的图片按钮。
// 它使用网页原生图片，能避开直接双击打开网页时 Phaser 读取本地图片失败的问题。
const MenuDomUI = {
  show({ onStart, onContinue, onLevels, onSettings, fragmentCount, fragmentTotal }) {
    const layer = document.getElementById('menu-ui-layer');
    if (!layer) return;
    layer.style.display = 'block';
    document.getElementById('menu-start').onclick = onStart;
    document.getElementById('menu-continue').onclick = onContinue;
    document.getElementById('menu-levels').onclick = onLevels;
    document.getElementById('menu-settings').onclick = onSettings;
    document.getElementById('fragment-count').textContent = `已收集碎片：${fragmentCount} / ${fragmentTotal}`;
  },

  hide() {
    const layer = document.getElementById('menu-ui-layer');
    if (!layer) return;
    layer.style.display = 'none';
    // 清空点击事件，避免离开主菜单后仍能触发旧场景的功能。
    ['menu-start', 'menu-continue', 'menu-levels', 'menu-settings'].forEach((id) => {
      document.getElementById(id).onclick = null;
    });
  },
};


/* ===== src/scenes/BaseScene.js ===== */

// 这是旧版公共场景底座：它会绘制深绿色背景和两处装饰圆形。
class BaseScene extends Phaser.Scene {
  createForestBackground() {
    this.add.rectangle(640, 360, 1280, 720, 0x193d31);
    this.add.circle(160, 100, 180, 0x4f8a61, 0.24);
    this.add.circle(1120, 640, 260, 0x7ca96d, 0.18);
  }

  goMainMenu() {
    this.scene.start(SCENE_KEYS.MAIN_MENU);
  }
}


/* ===== src/scenes/BootScene.js ===== */

// BootScene 是极短的启动页，专门负责把游戏带到资源准备画面。
class BootScene extends Phaser.Scene {
  constructor() { super(SCENE_KEYS.BOOT); }

  create() {
    this.scene.start(SCENE_KEYS.PRELOAD);
  }
}


/* ===== src/scenes/PreloadScene.js ===== */

// PreloadScene 负责加载角色序列帧，并用代码画出暂未替换的临时游戏物件。
// 日后替换更多游戏内图形时，可继续在 preload 里加载 assets 下的正式素材。
class PreloadScene extends Phaser.Scene {
  constructor() { super(SCENE_KEYS.PRELOAD); }

  preload() {
    // 这里故意不使用 Phaser 的 preload 读取本地 PNG。
    // 玩家直接双击 index.html 打开游戏时，部分浏览器会拦截 Phaser 加载本地图片，导致后面的菜单按钮不显示。
    // 所以角色图会在 create 里用浏览器原生 Image 加载，再交给 Phaser 做成动画纹理。
  }

  create() {
    this.createLoadingScreen();
    this.add.text(640, 330, '正在踏入森林遗迹……', { fontFamily: 'Microsoft YaHei', fontSize: '28px', color: '#fff6d1' }).setOrigin(0.5);
  }

  createLoadingScreen() {
    // 全屏黑色遮罩先盖住场景内容，让玩家只专注看到居中的加载过程。
    LoadingDomUI.show();

    this.prepareGameAssets().then(() => {
      // 游戏地图和图形由代码创建，因此使用启动动画清楚呈现“准备完成后才进入游戏”的过程。
      this.tweens.addCounter({
        from: 0,
        to: 100,
        duration: 1250,
        ease: 'Quad.Out',
        onUpdate: (tween) => LoadingDomUI.setProgress(tween.getValue()),
        onComplete: () => {
          LoadingDomUI.setProgress(100);
          this.time.delayedCall(180, () => {
            LoadingDomUI.hide();
            this.scene.start(SCENE_KEYS.MAIN_MENU);
          });
        },
      });
    }).catch((error) => {
      console.warn('角色图片加载失败，已使用临时角色保证游戏可进入。', error);
      this.createTextures();
      this.createFallbackPlayerTexture();
      this.createFallbackPlayerAnimations();
      LoadingDomUI.setProgress(100);
      this.time.delayedCall(180, () => {
        LoadingDomUI.hide();
        this.scene.start(SCENE_KEYS.MAIN_MENU);
      });
    });
  }

  async prepareGameAssets() {
    this.createTextures();
    await this.createLevelOneImageTextures();
    await this.createEndPanelImageTextures();
    await this.createPlayerSpriteSheetsFromImages();
    this.createPlayerAnimations();
  }


  async createLevelOneImageTextures() {
    // 第一关正式素材优先使用 index.html 提前加载的内嵌图片数据。
    // 这样直接双击本地 index.html 时，也不会因为浏览器拦截图片路径而显示绿色缺失贴图。
    const embeddedArt = window.LEVEL1_ART_DATA ?? {};
    const assets = [
      { key: 'level1-background', src: embeddedArt.background ?? './assets/images/level-01/background-forest-grid.jpg' },
      { key: 'level1-stones-a', src: embeddedArt.stonesA ?? './assets/images/level-01/obstacle-stones-a.png' },
      { key: 'level1-stones-b', src: embeddedArt.stonesB ?? './assets/images/level-01/obstacle-stones-b.png' },
      { key: 'level1-door', src: embeddedArt.door ?? './assets/images/level-01/door-wood.png' },
      { key: 'level1-key', src: embeddedArt.key ?? './assets/images/level-01/decor-key.png' },
      { key: 'level1-weapon', src: embeddedArt.weapon ?? './assets/images/level-01/decor-weapon.png' },
      { key: 'level1-fragment', src: embeddedArt.fragment ?? './assets/images/level-01/fragment-crystal.png' },
      { key: 'level1-home-button', src: embeddedArt.homeButton ?? './assets/images/level-01/button-home.png' },
      { key: 'level1-restart-button', src: embeddedArt.restartButton ?? './assets/images/level-01/button-restart.png' },
      { key: 'level1-guardian', src: embeddedArt.guardian ?? './assets/images/level-01/decor-guardian.png', frameWidth: 256, frameHeight: 256 },
    ];

    for (const asset of assets) {
      const image = await this.loadBrowserImage(asset.src);
      if (this.textures.exists(asset.key)) this.textures.remove(asset.key);
      if (asset.frameWidth) {
        this.textures.addSpriteSheet(asset.key, image, { frameWidth: asset.frameWidth, frameHeight: asset.frameHeight });
      } else {
        this.textures.addImage(asset.key, image);
      }
    }
  }

  async createEndPanelImageTextures() {
    // 通关和失败弹窗使用正式 UI 图片；即使这些图片加载失败，也不能影响角色素材。
    const embeddedArt = window.END_PANEL_ART_DATA ?? {};
    const assets = [
      { key: 'end-panel-board', src: embeddedArt.board ?? './assets/images/ui/end-panel/panel-board.png' },
      { key: 'end-panel-title-failed', src: embeddedArt.titleFailed ?? './assets/images/ui/end-panel/title-failed.png' },
      { key: 'end-panel-title-success', src: embeddedArt.titleSuccess ?? './assets/images/ui/end-panel/title-success.png' },
      { key: 'end-panel-button-next', src: embeddedArt.buttonNext ?? './assets/images/ui/end-panel/button-next.png' },
      { key: 'end-panel-button-retry', src: embeddedArt.buttonRetry ?? './assets/images/ui/end-panel/button-retry.png' },
      { key: 'end-panel-button-menu', src: embeddedArt.buttonMenu ?? './assets/images/ui/end-panel/button-menu.png' },
    ];

    for (const asset of assets) {
      try {
        const image = await this.loadBrowserImage(asset.src);
        if (this.textures.exists(asset.key)) this.textures.remove(asset.key);
        this.textures.addImage(asset.key, image);
      } catch (error) {
        console.warn(`弹窗图片加载失败，已保留文字弹窗兜底：${asset.key}`, error);
      }
    }
  }

  async createPlayerSpriteSheetsFromImages() {
    // 角色素材是 5 个方向：下、左下、左、左上、上。向右的方向通过水平翻转复用左侧素材。
    const embeddedSprites = window.PLAYER_SPRITE_DATA ?? {};
    const idleImage = await this.loadBrowserImage(embeddedSprites.idle ?? './assets/images/characters/player-idle-5dir.png');
    const walkImage = await this.loadBrowserImage(embeddedSprites.walk ?? './assets/images/characters/player-walk-5dir.png');

    this.addSpriteSheetTexture('player-idle-5dir', idleImage);
    this.addSpriteSheetTexture('player-walk-5dir', walkImage);
  }

  loadBrowserImage(src) {
    return new Promise((resolve, reject) => {
      const image = new Image();
      image.onload = () => resolve(image);
      image.onerror = () => reject(new Error(`无法加载图片：${src}`));
      image.src = src;
    });
  }

  addSpriteSheetTexture(key, image) {
    if (this.textures.exists(key)) this.textures.remove(key);
    const texture = this.textures.addSpriteSheet(key, image, {
      frameWidth: 256,
      frameHeight: 256,
    });
    // 如果没有被正确切成小格，角色会显示成一整条长图，所以这里主动拦截。
    if (!texture || texture.frameTotal <= 1) throw new Error(`角色序列帧切分失败：${key}`);
  }

  createTexture(key, draw) {
    const graphics = this.add.graphics();
    draw(graphics);
    graphics.generateTexture(key, 64, 64);
    graphics.destroy();
  }

  createPlayerAnimations() {
    const directions = [
      { name: 'down', row: 0 },
      { name: 'left-down', row: 1 },
      { name: 'left', row: 2 },
      { name: 'left-up', row: 3 },
      { name: 'up', row: 4 },
    ];

    directions.forEach(({ name, row }) => {
      this.anims.create({
        key: `player-idle-${name}`,
        frames: [{ key: 'player-idle-5dir', frame: row }],
        frameRate: 1,
      });
      this.anims.create({
        key: `player-walk-${name}`,
        frames: this.anims.generateFrameNumbers('player-walk-5dir', { start: row * 8, end: row * 8 + 7 }),
        frameRate: 10,
        repeat: -1,
      });
    });
  }

  createFallbackPlayerTexture() {
    // 兜底角色只在真实角色图加载失败时使用，目的是避免菜单和关卡因为素材问题整体消失。
    // 这里只生成单帧，不再生成一整条长图，避免画面上出现一串小人。
    const idle = this.add.graphics();
    this.drawFallbackGirl(idle, 128, 128, 0);
    idle.generateTexture('player-idle-5dir', 256, 256);
    idle.destroy();

    const walk = this.add.graphics();
    this.drawFallbackGirl(walk, 128, 128, 0, 8);
    walk.generateTexture('player-walk-5dir', 256, 256);
    walk.destroy();
  }

  drawFallbackGirl(g, centerX, centerY, directionRow, footOffset = 0) {
    const lookOffsetY = directionRow === 4 ? -8 : directionRow === 0 ? 8 : 0;
    g.fillStyle(0x143428, 0.25).fillEllipse(centerX, centerY + 72, 82, 24);
    g.fillStyle(0x6b4528).fillRoundedRect(centerX + 26, centerY + 10, 34, 48, 9);
    g.fillStyle(0xd9ad69).fillRoundedRect(centerX + 30, centerY + 22, 24, 14, 4);
    g.fillStyle(0x78b7c4).fillRoundedRect(centerX - 30, centerY + 2, 60, 70, 18);
    g.fillStyle(0x4d8998).fillTriangle(centerX - 31, centerY + 54, centerX + 31, centerY + 54, centerX, centerY + 96);
    g.fillStyle(0x2d3438).fillRoundedRect(centerX - 26 + footOffset, centerY + 88, 18, 12, 5);
    g.fillStyle(0x2d3438).fillRoundedRect(centerX + 8 - footOffset, centerY + 88, 18, 12, 5);
    g.fillStyle(0xf2c79f).fillCircle(centerX, centerY - 34, 32);
    g.fillStyle(0x6a3923).fillCircle(centerX, centerY - 55, 36).fillCircle(centerX - 30, centerY - 37, 14).fillCircle(centerX + 30, centerY - 37, 14);
    g.fillStyle(0xf2c79f).fillCircle(centerX, centerY - 28, 27);
    g.fillStyle(0x22323a).fillCircle(centerX - 10, centerY - 33 + lookOffsetY, 4).fillCircle(centerX + 10, centerY - 33 + lookOffsetY, 4);
    g.lineStyle(3, 0xaa5f55).lineBetween(centerX - 8, centerY - 17, centerX + 8, centerY - 17);
  }

  createFallbackPlayerAnimations() {
    const directions = ['down', 'left-down', 'left', 'left-up', 'up'];
    directions.forEach((name) => {
      this.anims.create({
        key: `player-idle-${name}`,
        frames: [{ key: 'player-idle-5dir', frame: 0 }],
        frameRate: 1,
      });
      this.anims.create({
        key: `player-walk-${name}`,
        frames: [{ key: 'player-walk-5dir', frame: 0 }],
        frameRate: 10,
        repeat: -1,
      });
    });
  }

  createTextures() {
    this.createTexture('floor', (g) => {
      g.fillStyle(0x779f64).fillRect(0, 0, 64, 64);
      g.fillStyle(0x8eb776).fillRoundedRect(3, 3, 58, 58, 7);
      g.fillStyle(0xa7c984, 0.55).fillCircle(14, 14, 8).fillCircle(48, 47, 10);
      g.fillStyle(0x658c58, 0.8).fillCircle(10, 48, 4).fillCircle(55, 19, 3);
      g.lineStyle(1, 0xc4dca0, 0.5).lineBetween(9, 28, 16, 22).lineBetween(16, 22, 21, 28).lineBetween(44, 14, 49, 8).lineBetween(49, 8, 53, 14);
      g.lineStyle(2, 0x5e8651, 0.34).strokeRoundedRect(3, 3, 58, 58, 7);
    });
    this.createTexture('floor-alt', (g) => {
      g.fillStyle(0x73965e).fillRect(0, 0, 64, 64);
      g.fillStyle(0x89ad6c).fillRoundedRect(3, 3, 58, 58, 7);
      g.fillStyle(0xb7cc91, 0.55).fillCircle(46, 15, 9).fillCircle(19, 50, 11);
      g.fillStyle(0x697f55).fillEllipse(17, 19, 9, 5).fillEllipse(47, 42, 10, 6);
      g.lineStyle(2, 0x4f7049, 0.48).lineBetween(7, 10, 13, 15).lineBetween(13, 15, 9, 20).lineBetween(54, 50, 58, 55).lineBetween(58, 55, 52, 58);
      g.lineStyle(2, 0x5e8651, 0.34).strokeRoundedRect(3, 3, 58, 58, 7);
    });
    this.createTexture('wall', (g) => {
      g.fillStyle(0x284938).fillRect(0, 0, 64, 64);
      g.fillStyle(0x526d59).fillRoundedRect(3, 3, 58, 58, 8);
      g.fillStyle(0x657e64).fillRoundedRect(6, 6, 25, 18, 4).fillRoundedRect(33, 6, 25, 18, 4).fillRoundedRect(5, 27, 20, 28, 4).fillRoundedRect(27, 27, 30, 28, 4);
      g.lineStyle(2, 0x2f493b).strokeRoundedRect(6, 6, 25, 18, 4).strokeRoundedRect(33, 6, 25, 18, 4).strokeRoundedRect(5, 27, 20, 28, 4).strokeRoundedRect(27, 27, 30, 28, 4);
      g.fillStyle(0x87a568, 0.78).fillCircle(9, 9, 5).fillCircle(57, 28, 5).fillCircle(24, 55, 4);
      g.lineStyle(2, 0x91ad75, 0.68).lineBetween(8, 12, 14, 18).lineBetween(57, 26, 53, 36).lineBetween(24, 53, 19, 58);
      g.lineStyle(3, 0x1f392e).strokeRoundedRect(2, 2, 60, 60, 9);
    });
    this.createTexture('box', (g) => {
      g.fillStyle(0x603821).fillRoundedRect(6, 8, 52, 49, 7);
      g.fillStyle(0xa96b3d).fillRoundedRect(9, 10, 46, 44, 5);
      g.fillStyle(0xce9256).fillRect(13, 14, 38, 7).fillRect(13, 29, 38, 7).fillRect(13, 44, 38, 6);
      g.lineStyle(3, 0x633b24).lineBetween(12, 24, 52, 24).lineBetween(12, 39, 52, 39).lineBetween(20, 12, 20, 52).lineBetween(44, 12, 44, 52);
      g.fillStyle(0xe2ac6a).fillCircle(17, 17, 2).fillCircle(47, 17, 2).fillCircle(17, 48, 2).fillCircle(47, 48, 2);
      g.lineStyle(2, 0x4a2b1b).strokeRoundedRect(6, 8, 52, 49, 7);
    });
    this.createTexture('heavy-box', (g) => {
      g.fillStyle(0x303c40).fillRoundedRect(5, 7, 54, 51, 7);
      g.fillStyle(0x687476).fillRoundedRect(9, 10, 46, 45, 5);
      g.fillStyle(0x8f9c9d).fillRect(14, 16, 36, 8).fillRect(14, 40, 36, 8);
      g.fillStyle(0xbac7c1).fillCircle(17, 17, 4).fillCircle(47, 17, 4).fillCircle(17, 48, 4).fillCircle(47, 48, 4);
      g.lineStyle(3, 0x3d4749).lineBetween(32, 11, 32, 54).lineBetween(10, 32, 54, 32);
      g.lineStyle(2, 0x1f292c).strokeRoundedRect(5, 7, 54, 51, 7);
    });
    this.createTexture('magic-box', (g) => {
      g.fillStyle(0x30265b).fillRoundedRect(6, 7, 52, 51, 8);
      g.fillStyle(0x6d5aaa).fillRoundedRect(9, 10, 46, 45, 6);
      g.lineStyle(2, 0xb6a4e8).strokeRoundedRect(13, 14, 38, 37, 4);
      g.fillStyle(0xc7b9f5).fillCircle(32, 32, 12);
      g.fillStyle(0x6d5aaa).fillCircle(32, 32, 6);
      g.fillStyle(0xdcd5ff).fillCircle(19, 18, 3).fillCircle(46, 18, 3).fillCircle(19, 47, 3).fillCircle(46, 47, 3);
    });
    this.createTexture('magic-box-active', (g) => {
      g.fillStyle(0x40266e).fillRoundedRect(5, 6, 54, 53, 9);
      g.fillStyle(0x8859c3).fillRoundedRect(9, 10, 46, 45, 6);
      g.lineStyle(3, 0xffe77a).strokeRoundedRect(11, 12, 42, 41, 5);
      g.fillStyle(0xfff1a1).fillCircle(32, 32, 13).fillCircle(17, 17, 3).fillCircle(47, 17, 3).fillCircle(17, 47, 3).fillCircle(47, 47, 3);
      g.fillStyle(0x8b4abb).fillCircle(32, 32, 6);
    });
    this.createTexture('button', (g) => { g.fillStyle(0x4a3024).fillEllipse(32, 43, 50, 19); g.fillStyle(0x9f6138).fillEllipse(32, 37, 43, 17); g.fillStyle(0xe8a75e).fillEllipse(32, 34, 32, 10); g.lineStyle(2, 0x69402a).strokeEllipse(32, 37, 43, 17); });
    this.createTexture('button-on', (g) => { g.fillStyle(0x4a3024).fillEllipse(32, 43, 50, 19); g.fillStyle(0x85603a).fillEllipse(32, 39, 43, 14); g.fillStyle(0xffe36e).fillEllipse(32, 38, 32, 8); });
    this.createTexture('special-button', (g) => { g.fillStyle(0x342650).fillEllipse(32, 43, 50, 19); g.fillStyle(0x7454a8).fillEllipse(32, 37, 43, 17); g.fillStyle(0xb79af1).fillEllipse(32, 34, 32, 10); });
    this.createTexture('special-button-on', (g) => { g.fillStyle(0x342650).fillEllipse(32, 43, 50, 19); g.fillStyle(0x62487e).fillEllipse(32, 39, 43, 14); g.fillStyle(0xffe87e).fillEllipse(32, 38, 32, 8); });
    this.createTexture('door-closed', (g) => { g.fillStyle(0x302d2a).fillRoundedRect(10, 2, 44, 60, 7); g.fillStyle(0x784b31).fillRoundedRect(14, 6, 36, 56, 4); g.fillStyle(0xa96b43).fillRect(18, 10, 28, 42); g.lineStyle(3, 0x5a3424).lineBetween(18, 25, 46, 25).lineBetween(18, 42, 46, 42); g.fillStyle(0xffd169).fillCircle(42, 35, 3); });
    this.createTexture('door-open', (g) => { g.fillStyle(0x203e34).fillRoundedRect(7, 2, 50, 60, 7); g.lineStyle(3, 0xdcc46f).strokeRoundedRect(9, 4, 46, 56, 5); g.fillStyle(0x74be7c, 0.75).fillCircle(32, 34, 14); g.lineStyle(2, 0xeef098, 0.8).strokeCircle(32, 34, 10); });
    this.createTexture('special-door-closed', (g) => { g.fillStyle(0x2d254a).fillRoundedRect(10, 2, 44, 60, 7); g.fillStyle(0x564382).fillRoundedRect(14, 6, 36, 56, 4); g.lineStyle(3, 0xc6b0f1).strokeRoundedRect(16, 8, 32, 52, 3); g.fillStyle(0xd4c5ff).fillCircle(32, 30, 10); });
    this.createTexture('special-door-open', (g) => { g.fillStyle(0x213b4c).fillRoundedRect(7, 2, 50, 60, 7); g.lineStyle(3, 0xe8d279).strokeRoundedRect(9, 4, 46, 56, 5); g.fillStyle(0xbaadff, 0.75).fillCircle(32, 34, 14); g.lineStyle(2, 0xf5edaa, 0.85).strokeCircle(32, 34, 10); });
    this.createTexture('exit', (g) => { g.fillStyle(0x254b42).fillCircle(32, 32, 28); g.fillStyle(0x44715d).fillCircle(32, 32, 24); g.lineStyle(4, 0xffdb74).strokeCircle(32, 32, 20); g.fillStyle(0xffed99).fillTriangle(32, 13, 49, 42, 15, 42); g.fillStyle(0xe3a94c).fillCircle(32, 34, 5); });
    this.createTexture('swamp', (g) => { g.fillStyle(0x193c34).fillCircle(32, 32, 29); g.fillStyle(0x335d47).fillCircle(32, 32, 24); g.lineStyle(3, 0x16342d).strokeCircle(32, 32, 19); g.lineStyle(2, 0x6f956c, 0.7).lineBetween(16, 23, 28, 29).lineBetween(42, 21, 32, 30).lineBetween(18, 42, 31, 35).lineBetween(47, 43, 36, 35); });
    this.createTexture('magic-zone', (g) => { g.fillStyle(0x594ea3, 0.32).fillCircle(32, 32, 27); g.fillStyle(0x7a6dca, 0.33).fillCircle(32, 32, 20); g.lineStyle(2, 0xf0d8ff, 0.9).strokeCircle(32, 32, 24).strokeCircle(32, 32, 13); g.fillStyle(0xe0c8ff).fillCircle(32, 8, 2).fillCircle(54, 39, 2).fillCircle(16, 46, 2); });
    // 碎片是每关必拿目标，使用金色菱形让它和钥匙、武器区分开。
    this.createTexture('fragment', (g) => { g.fillStyle(0x7f4f24).fillTriangle(32, 4, 54, 31, 32, 60).fillTriangle(32, 4, 10, 31, 32, 60); g.fillStyle(0xffd86b).fillTriangle(32, 7, 48, 31, 32, 55).fillTriangle(32, 7, 16, 31, 32, 55); g.fillStyle(0xfff3a6).fillTriangle(32, 10, 42, 30, 32, 45).fillCircle(32, 27, 4); g.lineStyle(2, 0xfff0a4).strokeTriangle(32, 4, 54, 31, 32, 60).strokeTriangle(32, 4, 10, 31, 32, 60); });
    // 钥匙会轻轻浮动，提醒玩家这是本关需要优先收集的目标。
    this.createTexture('key', (g) => { g.fillStyle(0x7a4a1d).fillCircle(23, 25, 14); g.fillStyle(0xffd968).fillCircle(23, 25, 11); g.fillStyle(0x7a4a1d).fillCircle(23, 25, 4); g.fillStyle(0xffd968).fillRect(31, 21, 23, 8).fillRect(45, 28, 7, 8).fillRect(37, 28, 6, 5); g.lineStyle(2, 0xfff2a6).strokeCircle(23, 25, 10); });
    // 武器是临时程序图形，后续可以替换成正式的短剑或探险工具素材。
    this.createTexture('weapon', (g) => { g.fillStyle(0x24343a).fillRoundedRect(29, 15, 7, 39, 3); g.fillStyle(0xd7e9ef).fillTriangle(32, 4, 42, 18, 22, 18); g.fillStyle(0xf4fbff).fillTriangle(32, 7, 37, 18, 32, 45); g.fillStyle(0x87552e).fillRoundedRect(20, 44, 24, 8, 3); g.fillStyle(0x6a3e22).fillRoundedRect(27, 49, 10, 12, 3); g.lineStyle(2, 0x17242a).strokeTriangle(32, 4, 42, 18, 22, 18).strokeRoundedRect(20, 44, 24, 8, 3); });
    // 守卫使用深色石像轮廓，与小女孩和草地保持明显的视觉区分。
    this.createTexture('guardian', (g) => { g.fillStyle(0x263d42).fillCircle(32, 18, 15); g.fillStyle(0x405f5f).fillRoundedRect(17, 29, 30, 27, 8); g.fillStyle(0x77918b).fillCircle(27, 18, 3).fillCircle(37, 18, 3); g.fillStyle(0x9bc28a).fillCircle(27, 18, 1.5).fillCircle(37, 18, 1.5); g.lineStyle(3, 0x172b31).strokeCircle(32, 18, 15).strokeRoundedRect(17, 29, 30, 27, 8); g.fillStyle(0x526f65).fillRect(12, 35, 7, 18).fillRect(45, 35, 7, 18); });
  }
}


/* ===== src/scenes/MainMenuScene.js ===== */

// 主菜单只负责带玩家进入不同功能，不存放关卡规则。
class MainMenuScene extends BaseScene {
  constructor() { super(SCENE_KEYS.MAIN_MENU); }

  create() {
    // 主菜单不绘制底色，让 index.html 直接显示用户提供的森林背景图。
    // 这种方式可兼容“直接双击 index.html 打开”的运行方式。
    this.cameras.main.setBackgroundColor('rgba(0,0,0,0)');

    const leaveMenu = (nextAction) => {
      // 只在玩家真的选择功能时隐藏网页按钮，不能在场景初始化时提前隐藏。
      MenuDomUI.hide();
      nextAction();
    };
    // 部分浏览器会拒绝自动播放声音。即使声音暂时不能开始，按钮也必须继续跳转。
    const startMusicSafely = () => {
      try {
        AudioManager.startMusic();
      } catch (error) {
        console.warn('背景音乐暂时无法播放，游戏仍可正常继续。', error);
      }
    };
    MenuDomUI.show({
      onStart: () => leaveMenu(() => { startMusicSafely(); this.scene.start(SCENE_KEYS.TUTORIAL); }),
      onContinue: () => leaveMenu(() => { startMusicSafely(); this.scene.start(SCENE_KEYS.GAME, { levelId: Math.min(GameState.unlockedLevel, 10) }); }),
      onLevels: () => leaveMenu(() => this.scene.start(SCENE_KEYS.LEVEL_SELECT)),
      onSettings: () => leaveMenu(() => this.scene.start(SCENE_KEYS.SETTINGS)),
      fragmentCount: GameState.fragments.length,
      fragmentTotal: LEVELS.length,
    });
  }
}


/* ===== src/scenes/TutorialScene.js ===== */

// 探险手册只负责展示操作规则；书页、按钮和文字由网页图片层组合，视觉素材更容易替换。
class TutorialScene extends BaseScene {
  constructor() { super(SCENE_KEYS.TUTORIAL); }

  create() {
    // 手册不再绘制 Phaser 背景，让 index.html 的菜单视频透过黑色遮罩显示出来。
    this.cameras.main.setBackgroundColor('rgba(0,0,0,0)');
    TutorialDomUI.show({
      onStart: () => {
        TutorialDomUI.hide();
        this.scene.start(SCENE_KEYS.GAME, { levelId: 1 });
      },
      onMenu: () => {
        TutorialDomUI.hide();
        this.goMainMenu();
      },
    });
    // 如果场景因其他方式关闭，也必须隐藏网页层，避免它覆盖之后的页面。
    this.events.once(Phaser.Scenes.Events.SHUTDOWN, () => TutorialDomUI.hide());
  }
}


/* ===== src/scenes/LevelSelectScene.js ===== */

// 关卡选择场景只负责读取游戏进度和处理跳转；具体画面由 LevelSelectDomUI 显示。
class LevelSelectScene extends BaseScene {
  constructor() {
    super(SCENE_KEYS.LEVEL_SELECT);
  }

  create() {
    // 让网页的图片层完整覆盖画布，同时保留底层视频作为其他页面的背景。
    this.cameras.main.setBackgroundColor('rgba(0,0,0,0)');

    LevelSelectDomUI.show({
      levels: LEVELS,
      unlockedLevel: GameState.unlockedLevel,
      completedLevels: GameState.completedLevels,
      onLevel: (levelId) => {
        AudioManager.beep(523.25);
        LevelSelectDomUI.hide();
        this.scene.start(SCENE_KEYS.GAME, { levelId });
      },
      onBack: () => {
        AudioManager.beep(440);
        LevelSelectDomUI.hide();
        this.goMainMenu();
      },
    });

    // 即使其他代码直接切换场景，也会同步关闭网页界面，避免遮住游戏画面。
    this.events.once(Phaser.Scenes.Events.SHUTDOWN, () => LevelSelectDomUI.hide());
  }
}


/* ===== src/scenes/SettingsScene.js ===== */

// 这是旧版设置页：中间会显示深色的弹窗底板。
class SettingsScene extends BaseScene {
  constructor() { super(SCENE_KEYS.SETTINGS); }

  create() {
    this.createForestBackground();
    UIFactory.createPanel(this, 640, 360, 650, 530);
    this.add.text(640, 165, '设置', { fontFamily: 'Microsoft YaHei', fontSize: '44px', color: '#fff1bd' }).setOrigin(0.5).setDepth(21);
    this.createVolumeRow('背景音乐', 285, 'musicVolume');
    this.createVolumeRow('音效', 385, 'soundVolume');
    const fullScreenText = this.add.text(640, 475, '', { fontFamily: 'Microsoft YaHei', fontSize: '22px', color: '#eaf3d8' }).setOrigin(0.5).setDepth(21);
    const fullScreenHint = this.add.text(640, 515, '', { fontFamily: 'Microsoft YaHei', fontSize: '16px', color: '#c4d7b7' }).setOrigin(0.5).setDepth(21);
    const refreshFullScreenText = () => fullScreenText.setText(`全屏显示：${FullscreenManager.isActive() ? '已开启' : '未开启'}`);
    const saveFullscreenState = () => {
      GameState.settings.fullscreen = FullscreenManager.isActive();
      GameState.save();
      refreshFullScreenText();
      fullScreenHint.setText('');
    };
    refreshFullScreenText();
    document.addEventListener('fullscreenchange', saveFullscreenState);
    document.addEventListener('webkitfullscreenchange', saveFullscreenState);
    this.events.once(Phaser.Scenes.Events.SHUTDOWN, () => {
      document.removeEventListener('fullscreenchange', saveFullscreenState);
      document.removeEventListener('webkitfullscreenchange', saveFullscreenState);
    });
    UIFactory.createButton(this, 485, 570, '切换全屏', async () => {
      try {
        fullScreenHint.setText('正在切换显示模式…');
        await FullscreenManager.toggle();
        this.time.delayedCall(80, saveFullscreenState);
      } catch (error) {
        fullScreenHint.setText('浏览器拒绝了全屏请求，请再点击一次按钮。');
        console.warn('全屏切换失败。', error);
      }
    }, 240);
    UIFactory.createButton(this, 795, 570, '返回菜单', () => this.goMainMenu(), 240);
  }

  createVolumeRow(label, y, settingKey) {
    const valueText = this.add.text(640, y, '', { fontFamily: 'Microsoft YaHei', fontSize: '24px', color: '#eaf3d8' }).setOrigin(0.5).setDepth(21);
    const refresh = () => valueText.setText(`${label}：${Math.round(GameState.settings[settingKey] * 100)}%`);
    refresh();
    UIFactory.createButton(this, 455, y, '－', () => { GameState.settings[settingKey] = Math.max(0, GameState.settings[settingKey] - 0.1); GameState.save(); refresh(); }, 70);
    UIFactory.createButton(this, 825, y, '＋', () => { GameState.settings[settingKey] = Math.min(1, GameState.settings[settingKey] + 0.1); GameState.save(); AudioManager.beep(600); refresh(); }, 70);
  }
}


/* ===== src/scenes/GameScene.js ===== */

// GameScene 是实际游玩的画面：它协调小女孩、遗迹地图与寻路冒险规则。
class GameScene extends BaseScene {
  constructor() {
    super(SCENE_KEYS.GAME);
  }

  init(data) {
    this.levelId = data.levelId ?? 1;
  }

  create() {
    this.level = LEVELS[this.levelId - 1];
    this.isLevelOneArt = this.level.id === 1;
    this.tileSize = this.isLevelOneArt ? 93 : TILE_SIZE;
    this.isEnded = false;
    this.hasWeapon = false;
    this.hasFragment = false;
    this.lastKeyBlockedAt = 0;
    this.playerSpeed = 190;
    this.createBackground();
    const mapWidth = Math.max(...this.level.map.map((row) => row.length)) * this.tileSize;
    this.offsetX = this.isLevelOneArt ? 100 : Math.floor((1280 - mapWidth) / 2);
    // 第一关参考图是 12×6 方格，这里用 93px 格子和 100/105 起点对齐底图方格。
    // 第一关正式底图的草地从木质提示栏下方开始，其它关卡仍然从画布顶部铺满。
    this.offsetY = this.isLevelOneArt ? 105 : 0;
    this.board = new Board(this, this.level, this.offsetX, this.offsetY, this.tileSize);
    this.board.build();
    const startPosition = this.board.gridToWorld(this.board.playerStart.x, this.board.playerStart.y);
    this.player = new Player(this, startPosition.x, startPosition.y);
    this.createHud();
    this.bindControls();
    AudioManager.startMusic();
  }

  createBackground() {
    if (this.isLevelOneArt) {
      // 第一关直接使用正式森林底图，画面会和参考图一致，不再显示旧的临时地砖底色。
      this.add.image(640, 360, 'level1-background').setDisplaySize(1280, 720).setDepth(0);
      return;
    }
    this.add.rectangle(640, 360, 1280, 720, 0x1b4638);
    this.add.circle(85, 690, 270, 0x6d9860, 0.2);
    this.add.circle(1190, 100, 220, 0x4c8060, 0.23);
  }

  createHud() {
    if (this.isLevelOneArt) {
      this.createLevelOneIconButton(61, 58, 'level1-home-button', () => this.goMainMenu());
      this.createLevelOneIconButton(139, 58, 'level1-restart-button', () => this.restartLevel());
      this.add.text(225, 31, '按住方向键 / WASD：自由移动    收集碎片、击败守卫、拿钥匙开门', {
        fontFamily: 'Microsoft YaHei',
        fontSize: '18px',
        color: '#fff1bd',
        fontStyle: 'bold',
      }).setOrigin(0, 0.5).setDepth(16);
      this.weaponStatusText = this.add.text(225, 66, '碎片：未收集    武器：未找到    守卫：未清除', {
        fontFamily: 'Microsoft YaHei',
        fontSize: '17px',
        color: '#fff1bd',
        fontStyle: 'bold',
      }).setOrigin(0, 0.5).setDepth(16);
      return;
    }

    // 关卡内的顶部区域只承担操作功能，不显示关卡名、步数或逃生门状态。
    this.add.rectangle(640, 40, 1280, 80, 0x102d25, 0.94).setDepth(15);
    UIFactory.createIconButton(this, 55, 40, 'home', '返回菜单', () => this.goMainMenu());
    UIFactory.createIconButton(this, 125, 40, 'restart', '重新开始', () => this.restartLevel());
    this.add.text(180, 28, '按住方向键 / WASD：自由移动    收集碎片、击败守卫、拿钥匙开门', {
      fontFamily: 'Microsoft YaHei',
      fontSize: '16px',
      color: '#dcebc9',
    }).setOrigin(0, 0.5).setDepth(16);
    this.weaponStatusText = this.add.text(180, 58, '碎片：未收集    武器：未找到    守卫：未清除', {
      fontFamily: 'Microsoft YaHei',
      fontSize: '15px',
      color: '#fff1bd',
    }).setOrigin(0, 0.5).setDepth(16);
  }

  createLevelOneIconButton(x, y, textureKey, action) {
    const button = this.add.image(x, y, textureKey).setScale(0.48).setDepth(30).setInteractive({ useHandCursor: true });
    button.on('pointerover', () => button.setScale(0.51));
    button.on('pointerout', () => button.setScale(0.48));
    button.on('pointerdown', () => { AudioManager.beep(523.25); action(); });
    return button;
  }
  bindControls() {
    this.keys = this.input.keyboard.addKeys({
      up: Phaser.Input.Keyboard.KeyCodes.UP,
      down: Phaser.Input.Keyboard.KeyCodes.DOWN,
      left: Phaser.Input.Keyboard.KeyCodes.LEFT,
      right: Phaser.Input.Keyboard.KeyCodes.RIGHT,
      w: Phaser.Input.Keyboard.KeyCodes.W,
      a: Phaser.Input.Keyboard.KeyCodes.A,
      s: Phaser.Input.Keyboard.KeyCodes.S,
      d: Phaser.Input.Keyboard.KeyCodes.D,
      restart: Phaser.Input.Keyboard.KeyCodes.R,
      pause: Phaser.Input.Keyboard.KeyCodes.ESC,
    });
    this.keys.restart.on('down', () => this.restartLevel());
    this.keys.pause.on('down', () => this.showPause());
  }

  update(time, delta) {
    if (this.isEnded || !this.player || !this.keys) return;

    this.updatePlayerMovement(delta);

    const touchedGuardian = this.board.updateGuardians(this.player.worldX, this.player.worldY, delta);
    if (touchedGuardian && this.hasWeapon) {
      this.board.defeatGuardian(touchedGuardian);
      AudioManager.beep(520, 0.2, 0.14);
      this.showHint('击败守卫！现在可以继续寻找钥匙。');
      this.updateWeaponStatus();
    } else if (touchedGuardian) {
      this.failLevel('你被巡逻守卫发现了，快换一条路线吧。');
      return;
    }
    this.checkCurrentArea();
  }

  updatePlayerMovement(delta) {
    const horizontal = Number(this.keys.right.isDown || this.keys.d.isDown) - Number(this.keys.left.isDown || this.keys.a.isDown);
    const vertical = Number(this.keys.down.isDown || this.keys.s.isDown) - Number(this.keys.up.isDown || this.keys.w.isDown);
    if (horizontal === 0 && vertical === 0) {
      this.player.stopMoving();
      return;
    }

    const vector = new Phaser.Math.Vector2(horizontal, vertical).normalize();
    const moveDistance = this.playerSpeed * (delta / 1000);
    const deltaX = vector.x * moveDistance;
    const deltaY = vector.y * moveDistance;
    this.tryMovePlayer(deltaX, deltaY);
  }

  tryMovePlayer(deltaX, deltaY) {
    let nextX = this.player.worldX;
    let nextY = this.player.worldY;

    // 横向和纵向分开判断，贴着墙移动时会自然滑过去，不会卡得很死。
    if (!this.board.isWorldBlocked(nextX + deltaX, nextY)) nextX += deltaX;
    if (!this.board.isWorldBlocked(nextX, nextY + deltaY)) nextY += deltaY;
    this.player.moveBy(nextX - this.player.worldX, nextY - this.player.worldY);
  }

  checkCurrentArea() {
    if (this.board.isWorldTile(this.player.worldX, this.player.worldY, TILE_TYPES.SWAMP)) {
      this.failLevel('小女孩掉进了沼泽陷坑。');
      return;
    }
    if (!this.hasWeapon && this.board.collectWeaponAtWorld(this.player.worldX, this.player.worldY)) {
      this.hasWeapon = true;
      AudioManager.beep(720, 0.18, 0.14);
      this.showHint('找到了武器！现在碰到守卫可以击败它。');
      this.updateWeaponStatus();
    }
    if (!this.hasFragment && this.board.collectFragmentAtWorld(this.player.worldX, this.player.worldY)) {
      this.hasFragment = true;
      GameState.collectFragment(`level-${this.level.id}`);
      AudioManager.beep(880, 0.2, 0.15);
      this.showHint('收集到本关碎片！继续寻找钥匙和出口。');
      this.updateWeaponStatus();
    }
    if (!this.board.areGuardiansCleared() && this.board.isNearKey(this.player.worldX, this.player.worldY)) {
      this.showKeyBlockedHint();
      return;
    }
    if (this.board.collectKeyAtWorld(this.player.worldX, this.player.worldY)) {
      AudioManager.beep(640, 0.16, 0.14);
    }
    // 收集所有钥匙后出口会打开，走进 D 就立即逃脱成功。
    if (this.board.isAtOpenDoor(this.player.worldX, this.player.worldY)) this.completeLevel();
  }

  updateWeaponStatus() {
    if (!this.weaponStatusText) return;
    const fragmentText = this.hasFragment ? '已收集' : '未收集';
    const weaponText = this.hasWeapon ? '已获得' : '未找到';
    const guardianText = this.board.areGuardiansCleared() ? '已清除' : '未清除';
    this.weaponStatusText.setText(`碎片：${fragmentText}    武器：${weaponText}    守卫：${guardianText}`);
  }

  showKeyBlockedHint() {
    const now = this.time.now;
    if (now - this.lastKeyBlockedAt < 900) return;
    this.lastKeyBlockedAt = now;
    AudioManager.beep(170, 0.07, 0.06);
    this.showHint('守卫还在保护钥匙，先找到武器击败守卫。');
  }

  showHint(message) {
    this.hintText?.destroy();
    this.hintText = this.add.text(640, 108, message, {
      fontFamily: 'Microsoft YaHei',
      fontSize: '18px',
      color: '#fff7d6',
      backgroundColor: 'rgba(14, 43, 34, 0.78)',
      padding: { x: 14, y: 8 },
    }).setOrigin(0.5).setDepth(30);
    this.tweens.add({
      targets: this.hintText,
      alpha: 0,
      duration: 360,
      delay: 950,
      onComplete: () => {
        this.hintText?.destroy();
        this.hintText = null;
      },
    });
  }

  restartLevel() {
    if (this.isEnded) return;
    this.scene.restart({ levelId: this.levelId });
  }

  failLevel(reason) {
    if (this.isEnded) return;
    this.isEnded = true;
    EventBus.emit(GAME_EVENTS.LEVEL_FAILED, { levelId: this.level.id, reason });
    this.showEndPanel({
      type: 'failed',
      title: '本关失败',
      description: reason,
      primaryLabel: '重新挑战',
      primaryAction: () => this.scene.restart({ levelId: this.levelId }),
    });
    AudioManager.beep(120, 0.35, 0.18);
  }

  completeLevel() {
    if (this.isEnded) return;
    this.isEnded = true;
    GameState.completeLevel(this.level.id);
    // 完成关卡后立刻刷新绿色填充部分，让本次成果立即反映在进度条上。
    EventBus.emit(GAME_EVENTS.LEVEL_COMPLETED, { levelId: this.level.id });
    const isLastLevel = this.level.id === LEVELS.length;
    this.showEndPanel({
      type: 'success',
      title: isLastLevel ? '遗迹小径，暂告一段落' : '逃脱成功！',
      description: isLastLevel ? '你已经集齐所有关卡碎片，找到了通往遗迹核心的道路。' : '你收集碎片并找齐钥匙，成功穿过出口。',
      primaryLabel: isLastLevel ? '返回关卡选择' : '下一关',
      primaryAction: () => {
        this.scene.start(isLastLevel ? SCENE_KEYS.LEVEL_SELECT : SCENE_KEYS.GAME, isLastLevel ? undefined : { levelId: this.level.id + 1 });
      },
    });
    AudioManager.beep(784, 0.28, 0.18);
  }

  showPause() {
    if (this.isEnded) return;
    this.isEnded = true;
    this.showEndPanel({
      title: '暂停中',
      description: '慢慢想，不着急。',
      primaryLabel: '继续游戏',
      primaryAction: () => { this.isEnded = false; this.clearOverlay(); },
    });
  }

  showEndPanel({ type = 'default', title, description, primaryLabel, primaryAction }) {
    const canUseImagePanel = (type === 'failed' || type === 'success') && this.textures.exists('end-panel-board');
    if (canUseImagePanel) {
      this.showImageEndPanel(type, description, primaryLabel, primaryAction);
      return;
    }
    this.showTextEndPanel(title, description, primaryLabel, primaryAction);
  }

  showImageEndPanel(type, description, primaryLabel, primaryAction) {
    this.overlay = this.add.container(0, 0).setDepth(40);
    const shade = this.add.rectangle(640, 360, 1280, 720, 0x071914, 0.52).setInteractive();
    const panel = this.add.image(640, 366, 'end-panel-board').setScale(0.88);
    const titleTexture = type === 'failed' ? 'end-panel-title-failed' : 'end-panel-title-success';
    const heading = this.add.image(640, 226, titleTexture).setScale(1);
    const detail = this.add.text(640, 334, description, {
      fontFamily: 'Microsoft YaHei',
      fontSize: '18px',
      color: '#604323',
      fontStyle: 'bold',
      align: 'center',
      wordWrap: { width: 450 },
    }).setOrigin(0.5);
    // 成功和失败弹窗底部保持两个并排按钮，和新的图片 UI 风格统一。
    const primaryTexture = this.getEndPanelButtonTexture(primaryLabel);
    const primary = primaryTexture
      ? this.createEndPanelImageButton(525, 430, primaryTexture, primaryAction)
      : UIFactory.createButton(this, 525, 430, primaryLabel, primaryAction, 240);
    const menu = this.createEndPanelImageButton(755, 430, 'end-panel-button-menu', () => this.scene.start(SCENE_KEYS.MAIN_MENU));
    this.overlay.add([shade, panel, heading, detail, primary, menu]);
  }

  getEndPanelButtonTexture(label) {
    return {
      下一关: 'end-panel-button-next',
      重新挑战: 'end-panel-button-retry',
      返回菜单: 'end-panel-button-menu',
    }[label];
  }

  createEndPanelImageButton(x, y, textureKey, action) {
    const normalScale = 1;
    const hoverScale = 1.04;
    const button = this.add.image(x, y, textureKey).setScale(normalScale).setInteractive({ useHandCursor: true });
    button.on('pointerover', () => button.setScale(hoverScale));
    button.on('pointerout', () => button.setScale(normalScale));
    button.on('pointerdown', () => { AudioManager.beep(523.25); action(); });
    return button;
  }

  showTextEndPanel(title, description, primaryLabel, primaryAction) {
    this.overlay = this.add.container(0, 0).setDepth(40);
    const shade = this.add.rectangle(640, 360, 1280, 720, 0x071914, 0.72).setInteractive();
    const panel = UIFactory.createPanel(this, 640, 360, 560, 310);
    const heading = this.add.text(640, 275, title, { fontFamily: 'Microsoft YaHei', fontSize: '37px', color: '#fff1bd' }).setOrigin(0.5).setDepth(41);
    const detail = this.add.text(640, 340, description, { fontFamily: 'Microsoft YaHei', fontSize: '20px', color: '#e2efd3', align: 'center', wordWrap: { width: 460 } }).setOrigin(0.5).setDepth(41);
    // 暂停等临时弹窗继续使用文字按钮，避免缺少专用图片时影响操作。
    const primary = UIFactory.createButton(this, 500, 450, primaryLabel, primaryAction, 240);
    const menu = UIFactory.createButton(this, 780, 450, '返回菜单', () => this.scene.start(SCENE_KEYS.MAIN_MENU), 240);
    this.overlay.add([shade, panel, heading, detail, primary, menu]);
  }

  clearOverlay() {
    this.overlay?.destroy(true);
    this.overlay = null;
  }
}


/* ===== src/main.js ===== */

// 把每个独立画面交给 Phaser 管理。以后新增“剧情页”等画面时，也在这个数组中登记。
const game = new Phaser.Game({
  ...GAME_CONFIG,
  scene: [
    BootScene,
    PreloadScene,
    MainMenuScene,
    TutorialScene,
    LevelSelectScene,
    SettingsScene,
    GameScene,
  ],
});

// 防止某些浏览器把 game 判定为“没有被使用”的变量；同时方便在浏览器调试时查看。
window.ruinsTrailGame = game;

// F11 在整个游戏内都可切换页面全屏。阻止默认行为可避免只放大浏览器窗口而不同步游戏界面。
window.addEventListener('keydown', async (event) => {
  if (event.key !== 'F11' || event.repeat) return;
  event.preventDefault();
  try {
    await FullscreenManager.toggle();
  } catch (error) {
    console.warn('F11 全屏切换失败，请使用设置中的切换全屏按钮。', error);
  }
});

